{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance user_data is not publicly exposed in the Launch Template",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "MEDIUM",
      "explanation": "The user_data field is not encrypted, potentially exposing sensitive information in the launch template."
    }
  ],
  "patched_code": "resource \"aws_launch_template\" \"changeme_simple_asg_launch_template_nlb\" {\n  name                   = \"changeme-simple-asg-launch-template-nlb\"\n  image_id               = data.aws_ami.changeme_amazon_nlb_ami.id\n  instance_type          = \"t2.micro\"\n  vpc_security_group_ids = [aws_security_group.changeme_nlb_aws_security_group.id]\n  user_data              = base64encode(tostring(file(\"${path.module}/user_data.sh\")))\n}",
  "fix_summary": "Replaced filebase64 with base64encode to ensure user_data is properly encoded and not directly exposing the file content."
}
